To create a CSV downloader using web workers in Ember Octane, follow these steps:

1. Install the necessary dependencies:

```bash
ember install ember-cli-htmlbars
ember install ember-cli-json-api
ember install ember-cli-web-worker
```

2. Create a new service for handling the CSV download:

```bash
touch app/services/csv-downloader.js
```

3. Implement the CSV downloader service:

```javascript
import Service from '@ember/service';
import { get } from '@ember/object';
import { inject as service } from '@ember/service';
import { task, timeout } from 'ember-concurrency';
import { read } from 'ember-cli-json-api';
import CSVBuilder from 'csv-builder';
import { worker } from 'ember-cli-web-worker';

export default Service.extend({
  store: service(),

  downloadCSV: task(function* (modelName, queryParams) {
    const { store } = this;
    const query = store.query(modelName, queryParams);

    // Fetch the data from the server
    const records = yield* read(query);

    // Create a new CSV Builder instance
    const csvBuilder = new CSVBuilder();

    // Add headers to the CSV Builder
    records[0].forEach((header) => {
      csvBuilder.addRow([header]);
    });

    // Add rows to the CSV Builder with the fetched data
    records.slice(1).forEach((row) => {
      csvBuilder.addRow(row);
    });

    // Create a Blob from the CSV data
    const csvData = csvBuilder.toString();
    const csvBlob = new Blob([csvData], { type: 'text/csv' });

    // Save the CSV file to the user's device
    const link = document.createElement('a');
    link.href = URL.createObjectURL(csvBlob);
    link.download = `${get(queryParams, 'filter') || modelName}.csv`;
    link.click();
  }),

  // Register the worker for the CSV Builder
  csvBuilderWorker: worker(function* (csvData) {
    const csvBuilder = new CSVBuilder();
    csvBuilder.addRow(csvData);
    return csvBuilder.toString();
  }),

  // Wrap the CSV Builder task with a timeout to handle long-running tasks
  downloadCSVWithTimeout: task(function* (modelName, queryParams) {
    const csvData = yield timeout(10000, this.downloadCSV.perform(modelName, queryParams));
    const csvBlob = yield this.csvBuilderWorker.perform(csvData);
    return csvBlob;
  }),
});
```

