```

Then, create a script (e.g., `compareExcel.js`) to read and compare the files:

```javascript
const XLSX = require('xlsx');
const _ = require('lodash');

function compareFiles(file1, file2, sheetName) {
  const workbook1 = XLSX.readFile(file1);
  const workbook2 = XLSX.readFile(file2);

  const sheet1 = workbook1.Sheets[sheetName];
  const sheet2 = workbook2.Sheets[sheetName];

  const keys1 = _.keys(sheet1);
  const keys2 = _.keys(sheet2);

  const differences = [];

  keys1.forEach((key1) => {
    const value1 = sheet1[key1].v;
    const key2 = _.findIndex(keys2, (key) => _.startsWith(key, key1)) + 1;

    if (key2 === -1) {
      differences.push(`Missing key "${key1}" in file 2`);
    } else {
      const value2 = sheet2[keys2[key2]].v;
      if (!_.isEqual(value1, value2)) {
        differences.push(`Key "${key1}" has different values: ${value1} (file 1) vs ${value2} (file 2)`);
      }
    }
  });

  keys2.forEach((key2) => {
    const key1 = _.findIndex(keys1, (key) => _.startsWith(key, key2)) + 1;

    if (key1 === -1) {
      differences.push(`Missing key "${key2}" in file 1`);
    }
  });

  return differences;
}

// Usage
const file1 = 'file1.xlsx';
const file2 = 'file2.xlsx';
const sheetName = 'Sheet1';

const differences = compareFiles(file1, file2, sheetName);
console.log(differences);
```

This script reads two Excel files (`file1.xlsx` and `file2.xlsx`) and compares the specified sheet (`Sheet1` in this example). It will output any differences it finds between the files.

